type PretextBreakKind = 'text' | 'space' | 'glue' | 'zero-width-break' | 'soft-hyphen';

type NormalizedMetricsStyle = {
  readonly fontFamily: string | readonly string[];
  readonly fontSize: number;
  readonly fontWeight: ParagraphFontWeight;
  readonly fontStyle: ParagraphFontStyle;
  readonly lineHeight: number;
  readonly locale?: string;
};

type InternalPretextPreparedTextWithSegments = PretextPreparedTextWithSegments & {
  readonly widths: readonly number[];
  readonly kinds: readonly PretextBreakKind[];
  readonly segLevels: Int8Array | null;
  readonly breakableWidths: readonly (readonly number[] | null)[];
  readonly breakablePrefixWidths: readonly (readonly number[] | null)[];
  readonly discretionaryHyphenWidth: number;
  readonly segments: readonly string[];
};

interface ResolvedStyleRun {
  readonly start: number;
  readonly end: number;
  readonly style: NormalizedMetricsStyle;
  readonly font: string;
}

interface ResolvedPretextParagraph {
  readonly text: string;
  readonly locale?: string;
  readonly maxLines?: number;
  readonly styleRuns: readonly ResolvedStyleRun[];
  readonly defaultStyle: NormalizedMetricsStyle;
  readonly isMixedLayoutStyle: boolean;
}

interface CursorTextOffsetResolver {
  offsetForCursor(cursor: PretextSourceLayoutCursor): number;
}

interface ParagraphLineMetrics {
  readonly lineHeight: number;
  readonly baseline: number;
}

interface ParagraphLayoutData {
  readonly prepared: InternalPretextPreparedTextWithSegments;
  readonly text: string;
  readonly styleRuns: readonly ResolvedStyleRun[];
  readonly defaultStyle: NormalizedMetricsStyle;
  readonly maxLines?: number;
  readonly isMixedLayoutStyle: boolean;
  readonly cursorResolver: CursorTextOffsetResolver;
}

interface CachedParagraphLayoutData {
  readonly data: ParagraphLayoutData;
}

interface InternalPretextCursor extends PretextSourceLayoutCursor {
  readonly lineIndex: number;
  readonly offset: number;
  readonly y: number;
}

export interface PretextTextGeometryBackendOptions {
  readonly adapter?: PretextAdapter;
  readonly defaultLocale?: string;
  readonly unconstrainedWidth?: number;
}

export interface PretextLayoutCursor {
  readonly segmentIndex: number;
  readonly graphemeIndex: number;
}

export interface PretextLineGeometry {
  readonly text: string;
  readonly width: number;
  readonly start: PretextLayoutCursor;
  readonly end: PretextLayoutCursor;
}

export interface PretextAdapter {
  prepareWithSegments(text: string, font: string): PretextPreparedTextWithSegments;
  layout(prepared: PretextPreparedTextWithSegments, maxWidth: number, lineHeight: number): {
    readonly lineCount: number;
    readonly height: number;
  };
  layoutWithLines(
    prepared: PretextPreparedTextWithSegments,
    maxWidth: number,
    lineHeight: number,
  ): PretextLayoutLinesResult;
  walkLineRanges(
    prepared: PretextPreparedTextWithSegments,
    maxWidth: number,
    onLine: (line: PretextLayoutLineRange) => void,
  ): number;
  layoutNextLine(
    prepared: PretextPreparedTextWithSegments,
    start: PretextSourceLayoutCursor,
    maxWidth: number,
  ): PretextLayoutLine | null;
  clearCache(): void;
  setLocale?(locale?: string): void;
}

