const DEFAULT_FONT_SIZE = 16;
const DEFAULT_LINE_HEIGHT_MULTIPLIER = 1.2;
const DEFAULT_FONT_FAMILY = 'sans-serif';
const DEFAULT_FONT_WEIGHT: ParagraphFontWeight = 'normal';
const DEFAULT_FONT_STYLE: ParagraphFontStyle = 'normal';
const DEFAULT_UNCONSTRAINED_WIDTH = 1_000_000;
const PRETEXT_GEOMETRY_ACCURACY = 'approximate' satisfies GeometryAccuracy;

