// Bounds the module-lifetime prepared-paragraph / layout caches (see
// BoundedLruMap) — large enough that typical scroll/chat surfaces stay
// entirely cache-hit, small enough to cap memory for long-lived sessions.
const DEFAULT_PARAGRAPH_CACHE_LIMIT = 2000;

function readInternalCursor(cursor: LineCursor | null): InternalPretextCursor {
  if (cursor === null) {
    return {
      lineIndex: 0,
      offset: 0,
      segmentIndex: 0,
      graphemeIndex: 0,
      y: 0,
    };
  }

  return cursor as unknown as InternalPretextCursor;
}

function createCursor(cursor: InternalPretextCursor): LineCursor {
  return cursor as unknown as LineCursor;
}

function quoteFontFamily(family: string): string {
  return /\s/.test(family) && !/^".*"$/.test(family) ? `"${family}"` : family;
}

function formatFontFamily(value: string | readonly string[] | undefined): string {
  if (Array.isArray(value)) {
    return value.map(quoteFontFamily).join(', ');
  }
  if (typeof value === 'string' && value.length > 0) {
    return quoteFontFamily(value);
  }
  return DEFAULT_FONT_FAMILY;
}

function buildFont(style: NormalizedMetricsStyle): string {
  return [
    style.fontStyle !== DEFAULT_FONT_STYLE ? style.fontStyle : null,
    style.fontWeight !== DEFAULT_FONT_WEIGHT ? String(style.fontWeight) : null,
    `${style.fontSize}px`,
    formatFontFamily(style.fontFamily),
  ]
    .filter((part): part is string => part !== null && part.length > 0)
    .join(' ');
}

function hasUnsupportedTextMetrics(style: ParagraphTextStyle | undefined): string | null {
  if (!style) {
    return null;
  }
  if (style.letterSpacing !== undefined && style.letterSpacing !== 0) {
    return 'letterSpacing';
  }
  if (style.fontVariantNumeric !== undefined) {
    return 'fontVariantNumeric';
  }
  if (style.fontFeatureSettings !== undefined) {
    return 'fontFeatureSettings';
  }
  if (style.fontVariationSettings !== undefined) {
    return 'fontVariationSettings';
  }
  return null;
}

function normalizeMetricsStyle(style: ParagraphTextStyle | undefined): NormalizedMetricsStyle {
  return {
    fontFamily: style?.fontFamily ?? DEFAULT_FONT_FAMILY,
    fontSize:
      typeof style?.fontSize === 'number' && Number.isFinite(style.fontSize) && style.fontSize > 0
        ? style.fontSize
        : DEFAULT_FONT_SIZE,
    fontWeight: style?.fontWeight ?? DEFAULT_FONT_WEIGHT,
    fontStyle: style?.fontStyle ?? DEFAULT_FONT_STYLE,
    lineHeight:
      typeof style?.lineHeight === 'number' && Number.isFinite(style.lineHeight) && style.lineHeight > 0
        ? style.lineHeight
        : (typeof style?.fontSize === 'number' && Number.isFinite(style.fontSize) && style.fontSize > 0
            ? style.fontSize
            : DEFAULT_FONT_SIZE) * DEFAULT_LINE_HEIGHT_MULTIPLIER,
    locale: style?.locale,
  };
}

function metricsStyleKey(style: NormalizedMetricsStyle): string {
  return JSON.stringify(style);
}

function flattenText(spec: ParagraphSpec): string {
  return spec.spans
    .map((span) => (span.type === 'text' ? span.text : ''))
    .join('');
}

function pushResolvedStyleRun(
  runs: ResolvedStyleRun[],
  run: ResolvedStyleRun,
): void {
  if (run.start >= run.end) {
    return;
  }

  const previous = runs[runs.length - 1];
  if (
    previous &&
    previous.end === run.start &&
    metricsStyleKey(previous.style) === metricsStyleKey(run.style)
  ) {
    runs[runs.length - 1] = {
      start: previous.start,
      end: run.end,
      style: previous.style,
      font: previous.font,
    };
    return;
  }

  runs.push(run);
}

function throwUnsupportedPretextFeature(feature: string): never {
  throw new Error(`@exact/text pretext backend does not support ${feature} yet.`);
}

function assertPretextParagraphSpecSupported(spec: ParagraphSpec): void {
  if (spec.baseDirection !== undefined && spec.baseDirection !== 'auto') {
    throwUnsupportedPretextFeature(`baseDirection="${spec.baseDirection}"`);
  }
  if (spec.writingMode !== undefined && spec.writingMode !== 'horizontal-tb') {
    throwUnsupportedPretextFeature(`writingMode="${spec.writingMode}"`);
  }
  if (spec.textAlign !== undefined && spec.textAlign !== 'auto') {
    throwUnsupportedPretextFeature(`textAlign="${spec.textAlign}"`);
  }
  if (spec.lineBreak !== undefined && spec.lineBreak !== 'normal') {
    throwUnsupportedPretextFeature(`lineBreak="${spec.lineBreak}"`);
  }
  if (spec.overflowWrap !== undefined && spec.overflowWrap !== 'normal') {
    throwUnsupportedPretextFeature(`overflowWrap="${spec.overflowWrap}"`);
  }
  if (spec.truncation !== undefined && spec.truncation !== 'none') {
    throwUnsupportedPretextFeature(`truncation="${spec.truncation}"`);
  }

  for (const span of spec.spans) {
    if (span.type !== 'text' || span.style === undefined) {
      continue;
    }
    if (span.style.writingMode !== undefined && span.style.writingMode !== 'horizontal-tb') {
      throwUnsupportedPretextFeature(`span writingMode="${span.style.writingMode}"`);
    }
    if (span.style.textAlign !== undefined && span.style.textAlign !== 'auto') {
      throwUnsupportedPretextFeature(`span textAlign="${span.style.textAlign}"`);
    }
  }
}

function resolveParagraph(
  spec: ParagraphSpec,
  defaultLocale: string | undefined,
): ResolvedPretextParagraph {
  const defaultStyle = normalizeMetricsStyle(undefined);
  let resolvedLocale = spec.locale ?? defaultLocale;
  let firstMetricsKey: string | null = null;
  let firstStyle = defaultStyle;
  let isMixedLayoutStyle = false;
  let offset = 0;
  const runs: ResolvedStyleRun[] = [];
  const textParts: string[] = [];

  for (const span of spec.spans) {
    if (span.type === 'attachment') {
      const attachment = span as ParagraphAttachmentSpan;
      throwUnsupportedPretextFeature(`attachment span "${attachment.id}"`);
    }

    const unsupportedField = hasUnsupportedTextMetrics(span.style);
    if (unsupportedField !== null) {
      throw new Error(
        `@exact/text pretext backend does not support ${unsupportedField} yet.`,
      );
    }

    if (span.style?.locale !== undefined) {
      if (resolvedLocale !== undefined && resolvedLocale !== span.style.locale) {
        throw new Error(
          '@exact/text pretext backend currently supports only one locale per paragraph.',
        );
      }
      resolvedLocale = span.style.locale;
    }

    if (span.text.length === 0) {
      continue;
    }

    const style = normalizeMetricsStyle(span.style);
    const styleKey = metricsStyleKey(style);
    if (firstMetricsKey === null) {
      firstMetricsKey = styleKey;
      firstStyle = style;
    } else if (styleKey !== firstMetricsKey) {
      isMixedLayoutStyle = true;
    }

    textParts.push(span.text);
    pushResolvedStyleRun(runs, {
      start: offset,
      end: offset + span.text.length,
      style,
      font: buildFont(style),
    });
    offset += span.text.length;
  }

  return {
    text: textParts.join(''),
    locale: resolvedLocale,
    maxLines: spec.maxLines,
    styleRuns: runs,
    defaultStyle: firstMetricsKey === null ? defaultStyle : firstStyle,
    isMixedLayoutStyle,
  };
}

function asInternalPreparedText(
  prepared: PretextPreparedTextWithSegments,
): InternalPretextPreparedTextWithSegments {
  return prepared as InternalPretextPreparedTextWithSegments;
}

function getSharedGraphemeSegmenter(): Intl.Segmenter {
  return new Intl.Segmenter(undefined, { granularity: 'grapheme' });
}

function getGraphemes(
  text: string,
  cache: Map<string, readonly string[]>,
): readonly string[] {
  const cached = cache.get(text);
  if (cached) {
    return cached;
  }

  const graphemes = Array.from(getSharedGraphemeSegmenter().segment(text), (entry) => entry.segment);
  cache.set(text, graphemes);
  return graphemes;
}

function measurePreparedTextWidth(
  adapter: PretextAdapter,
  prepared: PretextPreparedTextWithSegments,
  unconstrainedWidth: number,
): number {
  let widest = 0;
  adapter.walkLineRanges(prepared, unconstrainedWidth, (line) => {
    widest = Math.max(widest, line.width);
  });
  return widest;
}

function measureTextWidth(
  adapter: PretextAdapter,
  text: string,
  font: string,
  unconstrainedWidth: number,
  widthCache: Map<string, number>,
): number {
  if (text.length === 0) {
    return 0;
  }

  const cacheKey = `${font}\u0000${text}`;
  const cached = widthCache.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const width = measurePreparedTextWidth(
    adapter,
    adapter.prepareWithSegments(text, font),
    unconstrainedWidth,
  );
  widthCache.set(cacheKey, width);
  return width;
}

function measureRangeWidthWithStyles(
  adapter: PretextAdapter,
  text: string,
  rangeStart: number,
  rangeEnd: number,
  runs: readonly ResolvedStyleRun[],
  defaultFont: string,
  unconstrainedWidth: number,
  widthCache: Map<string, number>,
): number {
  if (rangeEnd <= rangeStart || text.length === 0) {
    return 0;
  }

  let width = 0;
  let matched = false;

  for (const run of runs) {
    if (run.end <= rangeStart || run.start >= rangeEnd) {
      continue;
    }

    matched = true;
    const overlapStart = Math.max(rangeStart, run.start);
    const overlapEnd = Math.min(rangeEnd, run.end);
    const sliceStart = overlapStart - rangeStart;
    const sliceEnd = overlapEnd - rangeStart;
    width += measureTextWidth(
      adapter,
      text.slice(sliceStart, sliceEnd),
      run.font,
      unconstrainedWidth,
      widthCache,
    );
  }

  if (!matched) {
    return measureTextWidth(
      adapter,
      text,
      defaultFont,
      unconstrainedWidth,
      widthCache,
    );
  }

  return width;
}

function measureBreakableSegmentGraphemes(
  adapter: PretextAdapter,
  text: string,
  segmentStart: number,
  runs: readonly ResolvedStyleRun[],
  defaultFont: string,
  unconstrainedWidth: number,
  widthCache: Map<string, number>,
  graphemeCache: Map<string, readonly string[]>,
): number[] | null {
  const graphemes = getGraphemes(text, graphemeCache);
  if (graphemes.length <= 1) {
    return null;
  }

  const widths: number[] = [];
  let offset = segmentStart;

  for (const grapheme of graphemes) {
    const end = offset + grapheme.length;
    widths.push(
      measureRangeWidthWithStyles(
        adapter,
        grapheme,
        offset,
        end,
        runs,
        defaultFont,
        unconstrainedWidth,
        widthCache,
      ),
    );
    offset = end;
  }

  return widths;
}

function toPrefixWidths(widths: readonly number[] | null): number[] | null {
  if (widths === null || widths.length <= 1) {
    return null;
  }

  let total = 0;
  return widths.map((width) => {
    total += width;
    return total;
  });
}

function buildCompositePreparedText(
  adapter: PretextAdapter,
  resolved: ResolvedPretextParagraph,
  unconstrainedWidth: number,
): InternalPretextPreparedTextWithSegments {
  const segmentationPrepared = asInternalPreparedText(
    adapter.prepareWithSegments(resolved.text, buildFont(resolved.defaultStyle)),
  );
  const widthCache = new Map<string, number>();
  const graphemeCache = new Map<string, readonly string[]>();
  const defaultFont = buildFont(resolved.defaultStyle);
  const widths: number[] = [];
  const breakableWidths: Array<number[] | null> = [];
  const breakablePrefixWidths: Array<number[] | null> = [];
  let textOffset = 0;

  for (let index = 0; index < segmentationPrepared.segments.length; index += 1) {
    const segmentText = segmentationPrepared.segments[index]!;
    const segmentStart = textOffset;
    const segmentEnd = segmentStart + segmentText.length;

    widths.push(
      measureRangeWidthWithStyles(
        adapter,
        segmentText,
        segmentStart,
        segmentEnd,
        resolved.styleRuns,
        defaultFont,
        unconstrainedWidth,
        widthCache,
      ),
    );

    if (segmentationPrepared.breakableWidths[index] !== null) {
      const graphemeWidths = measureBreakableSegmentGraphemes(
        adapter,
        segmentText,
        segmentStart,
        resolved.styleRuns,
        defaultFont,
        unconstrainedWidth,
        widthCache,
        graphemeCache,
      );
      breakableWidths.push(graphemeWidths);
      breakablePrefixWidths.push(toPrefixWidths(graphemeWidths));
    } else {
      breakableWidths.push(null);
      breakablePrefixWidths.push(null);
    }

    textOffset = segmentEnd;
  }

  let discretionaryHyphenWidth = segmentationPrepared.discretionaryHyphenWidth;
  const seenFonts = new Set<string>();
  for (const run of resolved.styleRuns) {
    if (seenFonts.has(run.font)) {
      continue;
    }
    seenFonts.add(run.font);
    discretionaryHyphenWidth = Math.max(
      discretionaryHyphenWidth,
      measureTextWidth(adapter, '-', run.font, unconstrainedWidth, widthCache),
    );
  }

  return {
    ...segmentationPrepared,
    widths,
    breakableWidths,
    breakablePrefixWidths,
    discretionaryHyphenWidth,
  };
}

function createCursorTextOffsetResolver(
  prepared: InternalPretextPreparedTextWithSegments,
): CursorTextOffsetResolver {
  const segmentStarts: number[] = [];
  let offset = 0;
  for (const segment of prepared.segments) {
    segmentStarts.push(offset);
    offset += segment.length;
  }

  const totalLength = offset;
  const graphemePrefixLengths = new Map<number, number[]>();

  function getPrefixLengths(segmentIndex: number): number[] {
    const cached = graphemePrefixLengths.get(segmentIndex);
    if (cached) {
      return cached;
    }

    const lengths: number[] = [];
    let prefixLength = 0;
    for (const grapheme of getSharedGraphemeSegmenter().segment(prepared.segments[segmentIndex]!)) {
      prefixLength += grapheme.segment.length;
      lengths.push(prefixLength);
    }
    graphemePrefixLengths.set(segmentIndex, lengths);
    return lengths;
  }

  return {
    offsetForCursor(cursor: PretextSourceLayoutCursor): number {
      if (cursor.segmentIndex >= prepared.segments.length) {
        return totalLength;
      }

      const baseOffset = segmentStarts[cursor.segmentIndex]!;
      if (cursor.graphemeIndex <= 0) {
        return baseOffset;
      }

      const prefixLengths = getPrefixLengths(cursor.segmentIndex);
      if (prefixLengths.length === 0) {
        return baseOffset;
      }

      const clampedIndex = Math.min(cursor.graphemeIndex - 1, prefixLengths.length - 1);
      return baseOffset + prefixLengths[clampedIndex]!;
    },
  };
}

function createParagraphLayoutData(
  adapter: PretextAdapter,
  resolved: ResolvedPretextParagraph,
  unconstrainedWidth: number,
): ParagraphLayoutData {
  const prepared = resolved.isMixedLayoutStyle
    ? buildCompositePreparedText(adapter, resolved, unconstrainedWidth)
    : asInternalPreparedText(
        adapter.prepareWithSegments(resolved.text, buildFont(resolved.defaultStyle)),
      );

  return {
    prepared,
    text: resolved.text,
    styleRuns: resolved.styleRuns,
    defaultStyle: resolved.defaultStyle,
    maxLines: resolved.maxLines,
    isMixedLayoutStyle: resolved.isMixedLayoutStyle,
    cursorResolver: createCursorTextOffsetResolver(prepared),
  };
}

function lineMetricsFromStyle(style: NormalizedMetricsStyle): ParagraphLineMetrics {
  return {
    lineHeight: style.lineHeight,
    baseline: Math.min(style.lineHeight, style.fontSize * 0.8),
  };
}

function resolveLineMetrics(
  textRange: TextRange,
  data: Pick<ParagraphLayoutData, 'defaultStyle' | 'styleRuns'>,
): ParagraphLineMetrics {
  let lineHeight = 0;
  let baseline = 0;

  for (const run of data.styleRuns) {
    if (run.end <= textRange.start || run.start >= textRange.end) {
      continue;
    }
    const metrics = lineMetricsFromStyle(run.style);
    lineHeight = Math.max(lineHeight, metrics.lineHeight);
    baseline = Math.max(baseline, metrics.baseline);
  }

  if (lineHeight <= 0) {
    return lineMetricsFromStyle(data.defaultStyle);
  }

  return {
    lineHeight,
    baseline,
  };
}

function clampVisibleLines<T>(
  lines: readonly T[],
  maxLines: number | undefined,
): readonly T[] {
  return typeof maxLines === 'number' && maxLines > 0
    ? lines.slice(0, maxLines)
    : lines;
}

function mapPretextLines(
  lines: readonly PretextLineGeometry[],
  data: ParagraphLayoutData,
): readonly ParagraphLine[] {
  const mapped: ParagraphLine[] = [];
  let y = 0;

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index]!;
    const textRange: TextRange = {
      start: data.cursorResolver.offsetForCursor(line.start),
      end: data.cursorResolver.offsetForCursor(line.end),
    };
    const metrics = resolveLineMetrics(textRange, data);

    mapped.push({
      geometryAccuracy: PRETEXT_GEOMETRY_ACCURACY,
      offsetUnit: PARAGRAPH_OFFSET_UNIT,
      index,
      textRange,
      width: line.width,
      height: metrics.lineHeight,
      baseline: metrics.baseline,
      origin: {
        x: 0,
        y,
      },
    });
    y += metrics.lineHeight;
  }

  return mapped;
}

function readMeasuredHeight(lines: readonly ParagraphLine[]): number {
  const last = lines[lines.length - 1];
  if (!last) {
    return 0;
  }
  return last.origin.y + last.height;
}

function measureUniformParagraph(
  adapter: PretextAdapter,
  data: ParagraphLayoutData,
  options: ParagraphMeasureOptions,
): ParagraphMetrics {
  const raw = adapter.layout(data.prepared, options.maxWidth, data.defaultStyle.lineHeight);
  let widest = 0;
  adapter.walkLineRanges(data.prepared, options.maxWidth, (line) => {
    widest = Math.max(widest, line.width);
  });

  const visibleLineCount =
    typeof data.maxLines === 'number' && data.maxLines > 0
      ? Math.min(raw.lineCount, data.maxLines)
      : raw.lineCount;

  return {
    geometryAccuracy: PRETEXT_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    width: widest,
    height: visibleLineCount * data.defaultStyle.lineHeight,
    lineCount: visibleLineCount,
    didTruncate: visibleLineCount < raw.lineCount,
  };
}

function measureMixedStyleParagraph(
  adapter: PretextAdapter,
  data: ParagraphLayoutData,
  options: ParagraphMeasureOptions,
): ParagraphMetrics {
  const raw = adapter.layoutWithLines(data.prepared, options.maxWidth, data.defaultStyle.lineHeight);
  const visibleLines = clampVisibleLines(raw.lines, data.maxLines);
  const mapped = mapPretextLines(visibleLines, data);

  return {
    geometryAccuracy: PRETEXT_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    width: mapped.reduce((widest, line) => Math.max(widest, line.width), 0),
    height: readMeasuredHeight(mapped),
    lineCount: mapped.length,
    didTruncate: visibleLines.length < raw.lineCount,
  };
}

function materializeLines(
  adapter: PretextAdapter,
  data: ParagraphLayoutData,
  maxWidth: number,
): readonly ParagraphLine[] {
  const raw = adapter.layoutWithLines(data.prepared, maxWidth, data.defaultStyle.lineHeight);
  return mapPretextLines(clampVisibleLines(raw.lines, data.maxLines), data);
}

function nextParagraphLine(
  adapter: PretextAdapter,
  data: ParagraphLayoutData,
  cursor: LineCursor | null,
  layoutOptions: { readonly maxWidth: number },
): ParagraphLineStep | null {
  const start = readInternalCursor(cursor);
  if (data.maxLines !== undefined && start.lineIndex >= data.maxLines) {
    return null;
  }

  const line = adapter.layoutNextLine(
    data.prepared,
    { segmentIndex: start.segmentIndex, graphemeIndex: start.graphemeIndex },
    layoutOptions.maxWidth,
  );
  if (line === null) {
    return null;
  }

  const textRange: TextRange = {
    start: start.offset,
    end: data.cursorResolver.offsetForCursor(line.end),
  };
  const metrics = resolveLineMetrics(textRange, data);
  const paragraphLine: ParagraphLine = {
    geometryAccuracy: PRETEXT_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    index: start.lineIndex,
    textRange,
    width: line.width,
    height: metrics.lineHeight,
    baseline: metrics.baseline,
    origin: {
      x: 0,
      y: start.y,
    },
  };

  return {
    line: paragraphLine,
    cursor: createCursor({
      lineIndex: start.lineIndex + 1,
      offset: textRange.end,
      segmentIndex: line.end.segmentIndex,
      graphemeIndex: line.end.graphemeIndex,
      y: start.y + paragraphLine.height,
    }),
  };
}

function layoutWithVariableWidths(
  adapter: PretextAdapter,
  data: ParagraphLayoutData,
  getWidthForLineY: ParagraphLineWidthResolver,
): readonly ParagraphLine[] {
  const lines: ParagraphLine[] = [];
  let cursor: LineCursor | null = null;

  while (data.maxLines === undefined || lines.length < data.maxLines) {
    const state = readInternalCursor(cursor);
    const step = nextParagraphLine(adapter, data, cursor, {
      maxWidth: getWidthForLineY(state.y),
    });
    if (step === null) {
      break;
    }
    lines.push(step.line);
    cursor = step.cursor;
  }

  return lines;
}

function intersectRangeRect(
  line: ParagraphLine,
  range: TextRange,
): ParagraphRangeRect | null {
  const lineStart = line.textRange.start;
  const lineEnd = line.textRange.end;
  const overlapStart = Math.max(range.start, lineStart);
  const overlapEnd = Math.min(range.end, lineEnd);

  if (overlapEnd <= overlapStart) {
    return null;
  }

  const lineLength = Math.max(1, lineEnd - lineStart);
  const startRatio = (overlapStart - lineStart) / lineLength;
  const endRatio = (overlapEnd - lineStart) / lineLength;

  return {
    geometryAccuracy: PRETEXT_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    lineIndex: line.index,
    rect: {
      x: line.origin.x + line.width * startRatio,
      y: line.origin.y,
      width: Math.max(1, line.width * (endRatio - startRatio)),
      height: line.height,
    },
  };
}

function hitTestLines(
  lines: readonly ParagraphLine[],
  point: Point,
  activeAnnotations: readonly ParagraphRangeAnnotation[],
): ParagraphHitTestResult | null {
  const line = lines.find(
    (candidate) =>
      point.y >= candidate.origin.y &&
      point.y < candidate.origin.y + candidate.height,
  );

  if (!line) {
    return null;
  }

  const lineLength = Math.max(1, line.textRange.end - line.textRange.start);
  const relativeX = point.x - line.origin.x;
  const clampedRatio =
    line.width > 0
      ? Math.max(0, Math.min(1, relativeX / line.width))
      : 0;
  const offset =
    line.textRange.start + Math.round(clampedRatio * lineLength);

  return {
    geometryAccuracy: PRETEXT_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    offset,
    affinity: relativeX <= line.width / 2 ? 'forward' : 'backward',
    isInside: relativeX >= 0 && relativeX <= line.width,
    activeAnnotations,
  };
}

function rangeAnnotationsAt(
  spec: ParagraphSpec,
  position: number,
): readonly ParagraphRangeAnnotation[] {
  const annotations = spec.ranges ?? [];
  if (annotations.length === 0) {
    return [];
  }

  return annotations.filter((annotation) => {
    const { start, end } = annotation.range;
    if (end === start) {
      return position === start;
    }
    return position >= start && position < end;
  });
}

export function createPretextTextGeometryBackend(
  options: PretextTextGeometryBackendOptions = {},
): SyncTextGeometryBackend {
  const adapter = options.adapter ?? defaultAdapter;
  const unconstrainedWidth = options.unconstrainedWidth ?? DEFAULT_UNCONSTRAINED_WIDTH;
  const cache = new BoundedLruMap<string, PreparedParagraph>(DEFAULT_PARAGRAPH_CACHE_LIMIT);
  const layoutCache = new BoundedLruMap<string, CachedParagraphLayoutData>(DEFAULT_PARAGRAPH_CACHE_LIMIT);
  let activeLocale = options.defaultLocale;

  return {
    capabilities: pretextTextGeometryCapabilities,
    geometryAccuracy: PRETEXT_GEOMETRY_ACCURACY,
    offsetUnit: PARAGRAPH_OFFSET_UNIT,
    prepare(spec: ParagraphSpec): PreparedParagraph {
      assertPretextParagraphSpecSupported(spec);
      const key = createParagraphKey(spec);
      const fullSpecKey = createFullParagraphKey(spec, key);
      const cached = cache.get(fullSpecKey);
      if (cached) {
        return cached;
      }

      let cachedLayout = layoutCache.get(key);
      if (!cachedLayout) {
        const resolved = resolveParagraph(spec, options.defaultLocale);

        if (adapter.setLocale && resolved.locale !== activeLocale) {
          adapter.setLocale(resolved.locale);
          activeLocale = resolved.locale;
        }

        cachedLayout = {
          data: createParagraphLayoutData(adapter, resolved, unconstrainedWidth),
        };
        layoutCache.set(key, cachedLayout);
      }

      const data = cachedLayout.data;
      const paragraph: PreparedParagraph = {
        capabilities: pretextTextGeometryCapabilities,
        geometryAccuracy: PRETEXT_GEOMETRY_ACCURACY,
        offsetUnit: PARAGRAPH_OFFSET_UNIT,
        handle: { key } as unknown as PreparedParagraph['handle'],
        spec,
        measure(measureOptions: ParagraphMeasureOptions): ParagraphMetrics {
          return data.isMixedLayoutStyle
            ? measureMixedStyleParagraph(adapter, data, measureOptions)
            : measureUniformParagraph(adapter, data, measureOptions);
        },
        minContentWidth(): number {
          let widest = 0;
          adapter.walkLineRanges(data.prepared, MIN_CONTENT_WIDTH, (line) => {
            widest = Math.max(widest, line.width);
          });
          return widest;
        },
        maxContentWidth(): number {
          let widest = 0;
          adapter.walkLineRanges(data.prepared, unconstrainedWidth, (line) => {
            widest = Math.max(widest, line.width);
          });
          return widest;
        },
        layoutLines(layoutOptions) {
          return materializeLines(adapter, data, layoutOptions.maxWidth);
        },
        nextLine(cursor, layoutOptions): ParagraphLineStep | null {
          return nextParagraphLine(adapter, data, cursor, layoutOptions);
        },
        layoutWithLineWidths(getWidthForLineY) {
          return layoutWithVariableWidths(adapter, data, getWidthForLineY);
        },
        rangeRects(range, layoutOptions): readonly ParagraphRangeRect[] {
          if (range.end <= range.start) {
            return [];
          }
          return this.layoutLines(layoutOptions)
            .map((line) => intersectRangeRect(line, range))
            .filter((value): value is ParagraphRangeRect => value !== null);
        },
        rangeAnnotationsAt(position): readonly ParagraphRangeAnnotation[] {
          return rangeAnnotationsAt(spec, position);
        },
        hitTest(point, layoutOptions): ParagraphHitTestResult | null {
          const result = hitTestLines(this.layoutLines(layoutOptions), point, []);
          if (result === null) {
            return null;
          }

          return {
            ...result,
            activeAnnotations: rangeAnnotationsAt(spec, result.offset),
          };
        },
      };

      cache.set(fullSpecKey, paragraph);
      return paragraph;
    },
    clearCache(): void {
      cache.clear();
      layoutCache.clear();
      adapter.clearCache();
      activeLocale = options.defaultLocale;
      if (adapter.setLocale) {
        adapter.setLocale(options.defaultLocale);
      }
    },
  };
}
